diff --git a/db/migrations/0042_row_level_security.sql b/db/migrations/0042_row_level_security.sql
new file mode 100644
index 0000000..e1b7c20
--- /dev/null
+++ b/db/migrations/0042_row_level_security.sql
@@ -0,0 +1,30 @@
+-- Tenant isolation in the database itself, not only in the query layer.
+-- app_rw owns these tables (it runs the migrations), and a table owner is exempt
+-- from its own policies unless FORCE is set.
+
+alter table projects enable row level security;
+alter table projects force row level security;
+alter table documents enable row level security;
+alter table documents force row level security;
+alter table comments enable row level security;
+alter table comments force row level security;
+
+create policy tenant_isolation on projects
+  using (tenant_id = current_setting('app.tenant_id')::uuid)
+  with check (tenant_id = current_setting('app.tenant_id')::uuid);
+
+create policy tenant_isolation on documents
+  using (tenant_id = current_setting('app.tenant_id')::uuid)
+  with check (tenant_id = current_setting('app.tenant_id')::uuid);
+
+create policy tenant_isolation on comments
+  using (tenant_id = current_setting('app.tenant_id')::uuid)
+  with check (tenant_id = current_setting('app.tenant_id')::uuid);
+
+-- New rows take the tenant from the request context.
+alter table projects alter column tenant_id set default current_setting('app.tenant_id')::uuid;
+alter table documents alter column tenant_id set default current_setting('app.tenant_id')::uuid;
+alter table comments alter column tenant_id set default current_setting('app.tenant_id')::uuid;
+
+create index if not exists documents_tenant_project_idx on documents (tenant_id, project_id);
+create index if not exists comments_tenant_document_idx on comments (tenant_id, document_id);
