index 7c2e1d4..f93a0b8 100644
--- a/api/src/db.ts
+++ b/api/src/db.ts
@@ -1,12 +1,28 @@
 import pg from 'pg';

 export const pool = new pg.Pool({
   connectionString: process.env.DATABASE_URL,
   max: 2,
   idleTimeoutMillis: 30_000,
 });

-export async function query<T>(sql: string, params: unknown[] = []): Promise<T[]> {
-  const res = await pool.query(sql, params);
-  return res.rows as T[];
+export type Db = {
+  query<T>(sql: string, params?: unknown[]): Promise<T[]>;
+};
+
+/**
+ * Runs fn with app.tenant_id set, so row-level security scopes every statement
+ * fn issues to that tenant.
+ */
+export async function withTenant<R>(tenantId: string, fn: (db: Db) => Promise<R>): Promise<R> {
+  const client = await pool.connect();
+  try {
+    await client.query("select set_config('app.tenant_id', $1, false)", [tenantId]);
+    const db: Db = {
+      query: async <T>(sql: string, params: unknown[] = []) => (await client.query(sql, params)).rows as T[],
+    };
+    return await fn(db);
+  } finally {
+    client.release();
+  }
 }
