@@ -0,0 +1,29 @@
+import { describe, it, expect, beforeAll } from 'vitest';
+import { withTenant } from '../src/db';
+import { seedTwoTenants } from './fixtures';
+
+// Runs against the docker-compose Postgres (direct, port 5432).
+describe('row-level security', () => {
+  let t: Awaited<ReturnType<typeof seedTwoTenants>>;
+
+  beforeAll(async () => {
+    t = await seedTwoTenants();
+  });
+
+  it('lists only the calling tenant documents', async () => {
+    const rows = await withTenant(t.a.tenantId, (db) => db.query<{ id: string }>('select id from documents'));
+    expect(rows.map((r) => r.id).sort()).toEqual(t.a.documentIds.sort());
+  });
+
+  it('refuses to write a row for another tenant', async () => {
+    await expect(
+      withTenant(t.a.tenantId, (db) =>
+        db.query('insert into documents (tenant_id, project_id, title) values ($1, $2, $3)', [
+          t.b.tenantId,
+          t.b.projectId,
+          'x',
+        ]),
+      ),
+    ).rejects.toThrow(/row-level security/);
+  });
+});

