diff --git a/infra/lib/notify.ts b/infra/lib/notify.ts
new file mode 100644
index 0000000..b13e6a0
--- /dev/null
+++ b/infra/lib/notify.ts
@@ -0,0 +1,27 @@
+import { Duration } from 'aws-cdk-lib';
+import * as lambda from 'aws-cdk-lib/aws-lambda';
+import * as sqs from 'aws-cdk-lib/aws-sqs';
+import * as cloudwatch from 'aws-cdk-lib/aws-cloudwatch';
+import * as actions from 'aws-cdk-lib/aws-cloudwatch-actions';
+import * as sns from 'aws-cdk-lib/aws-sns';
+import { Construct } from 'constructs';
+
+export function notifyFunction(scope: Construct, alarmTopicArn: string): lambda.Function {
+  const dlq = new sqs.Queue(scope, 'NotifyDlq', {
+    retentionPeriod: Duration.days(14),
+  });
+  new cloudwatch.Alarm(scope, 'NotifyDlqDepth', {
+    metric: dlq.metricApproximateNumberOfMessagesVisible(),
+    threshold: 1,
+    evaluationPeriods: 1,
+  }).addAlarmAction(new actions.SnsAction(sns.Topic.fromTopicArn(scope, 'NotifyAlarmTopic', alarmTopicArn)));
+  return new lambda.Function(scope, 'NotifyFn', {
+    runtime: lambda.Runtime.NODEJS_22_X,
+    architecture: lambda.Architecture.ARM_64,
+    handler: 'notify.handler',
+    code: lambda.Code.fromAsset('../services/reports/dist'),
+    timeout: Duration.seconds(30),
+    retryAttempts: 2,
+    deadLetterQueue: dlq,
+  });
+}
