+        "Key": { "pk": { "S": "{% 'ACCOUNT#' & $accountId %}" } }
+      },
+      "Assign": {
+        "current": "{% $number($states.result.Item.overdraftLimitMinor.N) %}"
+      },
+      "Catch": [
+        { "ErrorEquals": ["States.ALL"], "Next": "ReleaseRequest" }
+      ],
+      "Next": "NeedsApproval"
+    },
+    "NeedsApproval": {
+      "Type": "Choice",
+      "Choices": [
+        { "Condition": "{% $requested - $current <= 50000 %}", "Next": "ApplyLimit" }
+      ],
+      "Default": "RequestApproval"
+    },
+    "RequestApproval": {
+      "Type": "Task",
+      "Resource": "arn:aws:states:::sqs:sendMessage.waitForTaskToken",
+      "Arguments": {
+        "QueueUrl": "${risk_approvals_queue_url}",
+        "MessageBody": {
+          "requestId": "{% $requestId %}",
+          "accountId": "{% $accountId %}",
+          "currentMinor": "{% $current %}",
+          "requestedMinor": "{% $requested %}",
+          "taskToken": "{% $states.context.Task.Token %}"
+        }
+      },
+      "Catch": [
+        { "ErrorEquals": ["Risk.Declined"], "Next": "ClearRequest" },
+        { "ErrorEquals": ["States.ALL"], "Next": "ReleaseRequest" }
+      ],
+      "Next": "ApplyLimit"
+    },
+    "ApplyLimit": {
+      "Type": "Task",
+      "Resource": "arn:aws:states:::dynamodb:updateItem",
+      "Arguments": {
+        "TableName": "${accounts_table}",
+        "Key": { "pk": { "S": "{% 'ACCOUNT#' & $accountId %}" } },
+        "UpdateExpression": "SET overdraftLimitMinor = :limit REMOVE pendingLimitRequest",
+        "ConditionExpression": "pendingLimitRequest = :request",
+        "ExpressionAttributeValues": {
+          ":limit": { "N": "{% $string($requested) %}" },
+          ":request": { "S": "{% $requestId %}" }
+        }
+      },
+      "Catch": [
+        { "ErrorEquals": ["States.ALL"], "Next": "ReleaseRequest" }
+      ],
+      "Next": "NotifyChanged"
+    },
+    "NotifyChanged": {
+      "Type": "Task",
+      "Resource": "arn:aws:states:::events:putEvents",
+      "Arguments": {
+        "Entries": [
+          {
+            "Source": "banking.overdraft",
+            "DetailType": "OverdraftLimitChanged",
+            "Detail": { "accountId": "{% $accountId %}", "requestId": "{% $requestId %}", "limitMinor": "{% $requested %}" },
+            "EventBusName": "${event_bus_name}"
+          }
+        ]
+      },
+      "End": true
+    },
+    "ClearRequest": {
+      "Type": "Task",
+      "Resource": "arn:aws:states:::dynamodb:updateItem",
+      "Arguments": {
+        "TableName": "${accounts_table}",
+        "Key": { "pk": { "S": "{% 'ACCOUNT#' & $accountId %}" } },
+        "UpdateExpression": "REMOVE pendingLimitRequest",
+        "ConditionExpression": "pendingLimitRequest = :request",
+        "ExpressionAttributeValues": { ":request": { "S": "{% $requestId %}" } }
+      },
+      "Next": "NotifyDeclined"
+    },
+    "NotifyDeclined": {
+      "Type": "Task",
+      "Resource": "arn:aws:states:::events:putEvents",
+      "Arguments": {
+        "Entries": [
+          {
+            "Source": "banking.overdraft",
+            "DetailType": "OverdraftRequestDeclined",
+            "Detail": { "accountId": "{% $accountId %}", "requestId": "{% $requestId %}" },
+            "EventBusName": "${event_bus_name}"
+          }
+        ]
+      },
+      "End": true
+    },
+    "ReleaseRequest": {
+      "Type": "Task",
+      "Resource": "arn:aws:states:::dynamodb:updateItem",
+      "Arguments": {
+        "TableName": "${accounts_table}",
+        "Key": { "pk": { "S": "{% 'ACCOUNT#' & $accountId %}" } },
+        "UpdateExpression": "REMOVE pendingLimitRequest",
+        "ConditionExpression": "pendingLimitRequest = :request",
+        "ExpressionAttributeValues": { ":request": { "S": "{% $requestId %}" } }
+      },
+      "Next": "RequestFailed"
+    },
+    "RequestFailed": {
+      "Type": "Fail",
+      "Error": "Overdraft.RequestFailed",
+      "Cause": "The request could not be completed; the account's pending request was released."
+    }
+  }
+}
