diff --git a/services/overdraft/src/request.ts b/services/overdraft/src/request.ts
new file mode 100644
index 0000000..2d9a7e4
--- /dev/null
+++ b/services/overdraft/src/request.ts
@@ -0,0 +1,43 @@
+import { ConditionalCheckFailedException, DynamoDBClient } from '@aws-sdk/client-dynamodb';
+import { DynamoDBDocumentClient, UpdateCommand } from '@aws-sdk/lib-dynamodb';
+import { SFNClient, StartExecutionCommand } from '@aws-sdk/client-sfn';
+import type { APIGatewayProxyEventV2, APIGatewayProxyResultV2 } from 'aws-lambda';
+
+const ddb = DynamoDBDocumentClient.from(new DynamoDBClient({}));
+const sfn = new SFNClient({});
+
+// POST /accounts/{accountId}/overdraft-requests  { requestId, limitMinor }
+export const handler = async (event: APIGatewayProxyEventV2): Promise<APIGatewayProxyResultV2> => {
+  const accountId = event.pathParameters!.accountId!;
+  const { requestId, limitMinor } = JSON.parse(event.body ?? '{}');
+
+  try {
+    // One open request per account; the app shows "request pending" until it clears.
+    await ddb.send(
+      new UpdateCommand({
+        TableName: process.env.ACCOUNTS_TABLE,
+        Key: { pk: `ACCOUNT#${accountId}` },
+        UpdateExpression: 'SET pendingLimitRequest = :r',
+        ConditionExpression: 'attribute_not_exists(pendingLimitRequest) OR pendingLimitRequest = :r',
+        ExpressionAttributeValues: { ':r': requestId },
+      }),
+    );
+  } catch (err) {
+    if (err instanceof ConditionalCheckFailedException) {
+      return { statusCode: 409, body: JSON.stringify({ error: 'request_pending' }) };
+    }
+    throw err;
+  }
+
+  // The execution is named after the app's request id: a retried POST with the same
+  // id and body gets the running execution back instead of starting a second one.
+  const res = await sfn.send(
+    new StartExecutionCommand({
+      stateMachineArn: process.env.OVERDRAFT_STATE_MACHINE_ARN,
+      name: requestId,
+      input: JSON.stringify({ accountId, requestId, limitMinor }),
+    }),
+  );
+
+  return { statusCode: 202, body: JSON.stringify({ requestId, executionArn: res.executionArn }) };
+};
