--- /dev/null
+++ b/services/overdraft/src/decision.ts
@@ -0,0 +1,23 @@
+import { SFNClient, SendTaskFailureCommand, SendTaskSuccessCommand } from '@aws-sdk/client-sfn';
+
+const sfn = new SFNClient({});
+
+export interface Decision {
+  taskToken: string;
+  decision: 'approve' | 'decline';
+  officerId: string;
+  reason?: string;
+}
+
+// Invoked by the risk console when an officer approves or declines a request.
+export async function handleDecision(d: Decision): Promise<void> {
+  if (d.decision === 'approve') {
+    await sfn.send(
+      new SendTaskSuccessCommand({ taskToken: d.taskToken, output: JSON.stringify({ officerId: d.officerId }) }),
+    );
+    return;
+  }
+  await sfn.send(
+    new SendTaskFailureCommand({ taskToken: d.taskToken, error: 'Risk.Declined', cause: d.reason ?? 'declined' }),
+  );
+}
