diff --git a/services/renderer/src/page-cache.ts b/services/renderer/src/page-cache.ts
new file mode 100644
index 0000000..6c1d9e2
--- /dev/null
+++ b/services/renderer/src/page-cache.ts
@@ -0,0 +1,61 @@
+import { Cluster } from 'ioredis';
+import { gzipSync, gunzipSync } from 'node:zlib';
+
+const redis = new Cluster([{ host: process.env.CACHE_HOST!, port: 6379 }], {
+  dnsLookup: (address, callback) => callback(null, address),
+  redisOptions: { tls: {} },
+  scaleReads: 'master',
+});
+
+// Pages are written once and replaced or removed when the product changes
+// (see product-events.ts), so they stay until invalidated.
+const pageKey = (productId: string, locale: string) => `page:{product:${productId}}:${locale}`;
+const indexKey = (productId: string) => `page:{product:${productId}}:locales`;
+
+export async function getPage(productId: string, locale: string): Promise<string | null> {
+  const raw = await redis.getBuffer(pageKey(productId, locale));
+  return raw ? gunzipSync(raw).toString('utf8') : null;
+}
+
+export async function putPage(productId: string, locale: string, html: string): Promise<void> {
+  // Both keys share the {product:<id>} hash tag, so they live in one slot and the
+  // MULTI below is accepted by a cluster-mode endpoint.
+  await redis
+    .multi()
+    .set(pageKey(productId, locale), gzipSync(html))
+    .sadd(indexKey(productId), locale)
+    .exec();
+}
+
+export async function invalidateProduct(productId: string): Promise<void> {
+  const locales = await redis.smembers(indexKey(productId));
+  if (locales.length === 0) return;
+  await redis
+    .multi()
+    .del(...locales.map((l) => pageKey(productId, l)))
+    .del(indexKey(productId))
+    .exec();
+}
+
+export async function invalidateCategory(categoryId: string, productIds: AsyncIterable<string>) {
+  let n = 0;
+  for await (const productId of productIds) {
+    await invalidateProduct(productId);
+    n += 1;
+  }
+  return { categoryId, invalidated: n };
+}
+
+/** Operator tool: count cached pages without blocking the shards. */
+export async function countPages(): Promise<number> {
+  let total = 0;
+  for (const node of redis.nodes('master')) {
+    let cursor = '0';
+    do {
+      const [next, keys] = await node.scan(cursor, 'MATCH', 'page:*', 'COUNT', 1000);
+      total += keys.filter((k) => !k.endsWith(':locales')).length;
+      cursor = next;
+    } while (cursor !== '0');
+  }
+  return total;
+}
