diff --git a/web/build/emit-locales.mjs b/web/build/emit-locales.mjs
new file mode 100644
index 0000000..3b8e0f1
--- /dev/null
+++ b/web/build/emit-locales.mjs
@@ -0,0 +1,25 @@
+import { createHash } from 'node:crypto';
+import { readdir, readFile, writeFile, mkdir } from 'node:fs/promises';
+import path from 'node:path';
+
+// Writes dist/locales/<lang>.<hash>.json and a generated module with the file names,
+// so no unhashed JSON is ever served.
+const src = 'src/locales';
+const out = 'dist/locales';
+
+await mkdir(out, { recursive: true });
+const manifest = {};
+for (const file of await readdir(src)) {
+  if (!file.endsWith('.json')) continue;
+  const body = await readFile(path.join(src, file));
+  const hash = createHash('sha256').update(body).digest('hex').slice(0, 10);
+  const lang = path.basename(file, '.json');
+  const name = `${lang}.${hash}.json`;
+  await writeFile(path.join(out, name), body);
+  manifest[lang] = `/locales/${name}`;
+}
+await writeFile(
+  'src/i18n/manifest.gen.ts',
+  `export const localeFiles: Record<string, string> = ${JSON.stringify(manifest, null, 2)};\n`,
+);
+console.log(`emitted ${Object.keys(manifest).length} locale bundles`);
