+import { Cluster } from 'ioredis';
+
+const redis = new Cluster([{ host: process.env.CACHE_HOST!, port: 6379 }], {
+  dnsLookup: (address, callback) => callback(null, address),
+  redisOptions: { tls: {} },
+});
+
+const TTL_SECONDS = 15 * 60;
+const key = (locale: string, prefix: string) => `suggest:${locale}:${prefix.toLowerCase()}`;
+
+export async function getSuggestions(locale: string, prefix: string): Promise<string[] | null> {
+  const raw = await redis.get(key(locale, prefix));
+  return raw ? (JSON.parse(raw) as string[]) : null;
+}
+
+export async function putSuggestions(locale: string, prefix: string, items: string[]): Promise<void> {
+  // EX makes the key evictable under volatile-lru and bounds staleness to 15 minutes.
+  await redis.set(key(locale, prefix), JSON.stringify(items.slice(0, 10)), 'EX', TTL_SECONDS);
+}
