diff --git a/services/cards/src/decision.ts b/services/cards/src/decision.ts
new file mode 100644
index 0000000..3b7e2a9
--- /dev/null
+++ b/services/cards/src/decision.ts
@@ -0,0 +1,14 @@
+import { SFNClient, SendTaskFailureCommand, SendTaskSuccessCommand } from '@aws-sdk/client-sfn';
+
+const sfn = new SFNClient({});
+
+// Invoked by the risk console when an officer approves or declines a request.
+export async function handleDecision(d: { taskToken: string; decision: 'approve' | 'decline'; officerId: string }) {
+  if (d.decision === 'approve') {
+    await sfn.send(
+      new SendTaskSuccessCommand({ taskToken: d.taskToken, output: JSON.stringify({ officerId: d.officerId }) }),
+    );
+    return;
+  }
+  await sfn.send(new SendTaskFailureCommand({ taskToken: d.taskToken, error: 'Risk.Declined', cause: 'declined' }));
+}
